#include <iostream>
#include <string>
#include <sstream>
#include <regex>

std::string convertMarkdownToHTML(const std::string& markdown) {
    std::stringstream htmlStream;
    std::string token;

    // Headers
    std::regex headerRegex("^#{1,6} (.*)$");
    std::smatch headerMatch;

    while (std::regex_search(markdown, headerMatch, headerRegex)) {
        std::string headerLevel = headerMatch.prefix().str();
        std::string headerText = headerMatch[1].str();
        std::string htmlHeader = "<h" + headerLevel.length() + " class=\"markdown-header\">" + headerText + "</h" + headerLevel.length() + ">";
        htmlStream << htmlHeader << std::endl;
        markdown.erase(headerMatch.position(), headerMatch.length());
    }

    // Bold and italic text
    std::regex boldRegex("\\*([^*]*)\\*");
    std::regex italicRegex("_(.*)_");
    std::smatch boldMatch, italicMatch;

    while (std::regex_search(markdown, boldMatch, boldRegex)) {
        std::string boldText = boldMatch[1].str();
        std::string htmlBold = "<strong>" + boldText + "</strong>";
        htmlStream << htmlBold << std::endl;
        markdown.erase(boldMatch.position(), boldMatch.length());
    }

    while (std::regex_search(markdown, italicMatch, italicRegex)) {
        std::string italicText = italicMatch[1].str();
        std::string htmlItalic = "<em>" + italicText + "</em>";
        htmlStream << htmlItalic << std::endl;
        markdown.erase(italicMatch.position(), italicMatch.length());
    }

    // Links
    std::regex linkRegex("\\[([^\\[]*)\\]\\\\(([^\\)]*)\\)");
    std::smatch linkMatch;

    while (std::regex_search(markdown, linkMatch, linkRegex)) {
        std::string linkText = linkMatch[1].str();
        std::string linkURL = linkMatch[2].str();
        std::string htmlLink = "<a href=\"" + linkURL + "\" target=\"_blank\">" + linkText + "</a>";
        htmlStream << htmlLink << std::endl;
        markdown.erase(linkMatch.position(), linkMatch.length());
    }

    // Blockquotes
    std::regex blockquoteRegex("^> (.*)$");
    std::smatch blockquoteMatch;

    while (std::regex_search(markdown, blockquoteMatch, blockquoteRegex)) {
        std::string blockquoteText = blockquoteMatch[1].str();
        std::string htmlBlockquote = "<blockquote>" + blockquoteText + "</blockquote>";
        htmlStream << htmlBlockquote << std::endl;
        markdown.erase(blockquoteMatch.position(), blockquoteMatch.length());
    }

    // Lists
    std::regex unorderedListRegex("^\\*\\s(.*)$|^-\\s(.*)$");
    std::regex orderedListRegex("^\\d+\\.\\s(.*)$");
    std::smatch listMatch;

    while (std::regex_search(markdown, listMatch, unorderedListRegex)) {
        std::string listText = listMatch[1].str();
        std::string htmlList = "<ul><li>" + listText + "</li></ul>";
        htmlStream << htmlList << std::endl;
        markdown.erase(listMatch.position(), listMatch.length());
    }

    while (std::regex_search(markdown, listMatch, orderedListRegex)) {
        std::string listText = listMatch[1].str();
        std::string htmlList = "<ol><li>" + listText + "</li></ol>";
        htmlStream << htmlList << std::endl;
        markdown.erase(listMatch.position(), listMatch.length());
    }

    // Code blocks
    std::regex codeBlockRegex("^```(.*?)\\n(.*)\\n```$");
    std::smatch codeBlockMatch;

    while (std::regex_search(markdown, codeBlockMatch, codeBlockRegex)) {
        std::string language = codeBlockMatch[1].str();
        std::string code = codeBlockMatch[2].str();
        std::string htmlCode = "<pre><code class=\"" + language + "\">" + code + "</code></pre>";
        htmlStream << htmlCode << std::endl;
        markdown.erase(codeBlockMatch.position(), codeBlockMatch.length());
    }

    // Remaining text
    htmlStream << markdown << std::endl;

    return htmlStream.str();
}

int main() {
