```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string palabra; // palabra a buscar
    int apariciones = 0; // contador de apariciones

    // leer la palabra a buscar desde el usuario
    cout << "Introduzca la palabra a buscar: ";
    cin >> palabra;

    // leer el nombre del archivo desde el usuario
    string archivo;
    cout << "Introduzca el nombre del archivo: ";
    cin >> archivo;

    // abrir el archivo para lectura
    ifstream file(archivo);
    if (!file) {
        cout << "Error al abrir el archivo." << endl;
        return 1;
    }

    string linea; // línea actual del archivo

    // leer línea por línea del archivo
    while (getline(file, linea)) {
        // contar las apariciones de la palabra en la línea actual
        size_t pos = 0;
        while ((pos = linea.find(palabra, pos)) != string::npos) {
            pos += palabra.length();
            apariciones++;
        }
    }

    // cerrar el archivo
    file.close();

    // imprimir el resultado
    cout << "La palabra \"" << palabra << "\" aparece " << apariciones << " veces en el archivo " << archivo << endl;

    return 0;
}
```

Este programa utiliza las bibliotecas `fstream` y `string` para leer y contar las apariciones de una palabra en un archivo de texto. Primero, el usuario introduce la palabra a buscar y el nombre del archivo a leer. Luego, el programa abre el archivo para lectura, lee línea por línea, cuenta las apariciones de la palabra en cada línea y almacena el resultado en una variable. Finalmente, el programa cierra el archivo y muestra el resultado al usuario.

